CREATE COLUMN TABLE "TEST_AP"."OBAT" ("AbsEntry" INTEGER CS_INT NOT NULL , "FldAbs" INTEGER CS_INT NOT NULL , "AttrValue" NVARCHAR(20) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Transfered" NVARCHAR(1) DEFAULT 'N', "Instance" SMALLINT CS_INT DEFAULT 0, "LogInstanc" INTEGER CS_INT DEFAULT 0, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "Deleted" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBAT_BUSINESS_K" ON "TEST_AP"."OBAT" ( "FldAbs" ASC, "AttrValue" ASC )